INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-BAG-000', 'bag', NULL, 'bag', 'KIDAN 72 Preparedness Bag', 'Complete system', 'The full 72-hour system: the primary bag with the KIDAN Black and the KIDAN Brown packed inside.', 'Everything one person needs for the first 72 hours after a typhoon, flood or evacuation. The primary bag holds the KIDAN Black and the KIDAN Brown, so you can grab the whole system at once or split it between family members.', '', NULL, '', '', NULL, '[["Configuration","Primary bag + KIDAN Black + KIDAN Brown"],["Coverage","1 person · 72 hours"],["Contents","Everything in the KIDAN Black and the KIDAN Brown"],["Registration","Logged in the KIDAN 72 Database with owner profile, inventory and expiry dates"],["Inspection","Monthly function check · Quarterly full inspection"]]', '', '', NULL, 1, 0, 1, 10);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-BAG-001', 'bag', NULL, 'aid', 'KIDAN Black', 'Sustainment module', 'Medical kit, food, electronic needs and documents.', 'Medical kit, food, electronic needs and documents: everything that keeps you fed, treated and connected, plus the papers you need after an evacuation.', '', NULL, '', '', NULL, '[["Role","Medical kit, food, electronic needs and documents"],["Colour","Black"],["Carry","Inside the Preparedness Bag, or on its own"]]', '', '', NULL, 2, 0, 1, 20);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-BAG-002', 'bag', NULL, 'tool', 'KIDAN Brown', 'Field module', 'Tools and gear.', 'Tools and gear: everything for darkness, rain, shelter and moving safely.', '', NULL, '', '', NULL, '[["Role","Tools and gear"],["Colour","Brown"],["Carry","Inside the Preparedness Bag, or on its own"]]', '', '', NULL, 1, 0, 1, 30);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTR-001', 'item', 'WTR', 'filter', 'Water Purifying Kit', '', 'Chlorine tablets in an amber bottle, kept dry with silica gel, to make collected water safer to drink.', '', 'Tap water and refilling stations can stop for days after a typhoon. Treating rainwater or well water lets you stretch your supply. Never drink floodwater, even after treatment.', '["Collect the clearest water you can find and let any dirt settle.","Pour it through a clean cloth into a clean container.","Add chlorine tablets following the dose printed on the pack, then close the container.","Wait the full time stated on the pack before drinking."]', 'Amber bottle · Silica gel · Chlorine tablets', 'Check the tablet expiry date every 6 months. Replace the silica gel if it changes colour or clumps.', '["Amber bottle","Silica gel","Chlorine tablets"]', NULL, 'how to use chlorine tablets purify water emergency', '', NULL, 1, 0, 1, 10);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTR-002', 'item', 'WTR', 'cup', 'Collapsible Silicone Cup', '', 'A cup that folds flat, for hot and cold drinks and food.', '', 'Space in a go-bag is limited. A folding cup gives you a clean drinking vessel without taking room.', '["Pull the cup open from the base until it locks into shape.","Rinse it with clean water before first use.","After use, wipe it dry and press it flat to pack it."]', 'Food-grade silicone, folds flat', 'Keep it clean and dry before packing to prevent mould.', NULL, NULL, 'collapsible silicone cup camping', '', NULL, 1, 0, 1, 20);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTR-003', 'item', 'WTR', 'cup', 'Collapsible Metal Cup', '', 'For drinking and boiling water.', '', 'Warm water and drinks help you stay comfortable at night and after getting wet. A metal cup can be used with your fire starter kit.', '["Extend the cup to its full height before filling.","To warm water, set it beside a small fire, not inside it, and hold it by the handle with a cloth.","Let it cool before collapsing it back down."]', 'Metal, collapsible', 'Dry it fully after use to prevent rust or stains.', NULL, NULL, 'collapsible metal cup camping', '', NULL, 1, 0, 1, 30);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-FOD-001', 'item', 'FOD', 'food', 'Shelf-Stable Food (MRE)', '', 'High-energy bar, shelf stable for 24 years.', '', 'Electricity and LPG may be cut for days. Ready-to-eat food keeps your energy up without cooking.', '["Check the expiry date when you pack it.","Open the pack and follow the eating or heating instructions printed on it.","Eat in a dry, clean spot and pack the wrapper away as rubbish."]', 'High-energy bar, 24-year shelf life', 'Log the expiry date and replace it at least one month before it expires.', NULL, NULL, 'MRE meal ready to eat how to use', '', NULL, 1, 0, 1, 40);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-FOD-002', 'item', 'FOD', 'honey', 'Honey', '', 'Raw honey for quick energy.', '', 'Honey gives fast energy when you are tired, cold or stressed, and it keeps for a very long time if sealed.', '["Take a spoonful or two when you need quick energy.","Close the bottle tightly after every use.","Do not give honey to babies under one year old."]', 'Sealed bottle', 'Check the seal regularly. Honey can thicken over time, which is normal.', NULL, NULL, 'honey emergency food energy', '', NULL, 1, 0, 1, 50);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-FOD-003', 'item', 'FOD', 'salt', 'Salt', '', 'A pack of sea salt for seasoning, preserving food and replacing salt lost through sweat.', '', 'Hot, humid conditions and hard work make you sweat. Salt helps with taste and can preserve food you catch.', '["Use a small pinch to season food.","Keep it closed so it stays dry.","Store it in the salt pouch to keep moisture out."]', 'Food-grade salt', 'Keep it sealed and dry. Replace it if it gets wet.', NULL, NULL, 'salt survival uses', '', NULL, 1, 0, 1, 60);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-FOD-005', 'item', 'FOD', 'spoon', 'Tactical Spoon (Black)', '', '5-in-1 multi-functional EDC stainless steel spoon.', '', 'You may have no kitchen tools after an evacuation. A sturdy spoon makes eating cleaner and easier.', '["Wipe or rinse the spoon before eating.","Use it to eat directly from your food pack.","Clean it with a wipe after use and pack it away."]', '5-in-1, stainless steel, black', 'Keep it clean and stored in the pouch.', NULL, NULL, '', '', NULL, 1, 0, 1, 70);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-FOD-006', 'item', 'FOD', 'spoon', 'Foldable Spoon', '', 'Stainless steel spork.', '', 'Each person needs their own utensil. A folding spoon fits easily in a pouch.', '["Unfold the spoon until it locks open.","Use it to eat or stir.","Clean it, fold it and pack it away."]', 'Foldable, stainless steel', 'Check that the hinge still locks. Keep it clean and dry.', NULL, NULL, '', '', NULL, 1, 0, 1, 80);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-MED-001', 'item', 'MED', 'aid', 'First Aid Kit', '', 'Basic supplies for cleaning, covering and protecting cuts, scrapes and small injuries.', '', 'Clinics may be crowded or hard to reach after a disaster. Cuts from debris, especially near floodwater, need quick cleaning and cover.', '["Learn where everything is in the kit before you need it.","Clean the wound with clean water before treating it.","Press firmly with gauze to control bleeding, then cover the wound.","Seek medical help for deep wounds, heavy bleeding or signs of infection."]', 'Basic wound-care supplies', 'Check the kit every 3 months. Replace anything used or expired.', NULL, NULL, 'basic first aid kit how to use wound care', '', NULL, 1, 0, 1, 90);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-LGT-001', 'item', 'LGT', 'head', 'Headlamp', '', 'Rechargeable headlamp with motion sensor and 5 modes. Removable battery.', '', 'Power is often out for days. A headlamp lets you work, walk and help others in the dark with both hands free.', '["Adjust the strap so it sits firmly on your forehead.","Switch it on and choose the lowest brightness that works, to save battery.","Angle it down so you don''t blind the people around you.","Charge it whenever you have power."]', 'Rechargeable, motion sensor, 5 modes, removable battery', 'Test it every month and keep it charged.', NULL, NULL, 'how to use headlamp', '', NULL, 1, 0, 1, 100);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-LGT-002', 'item', 'LGT', 'torch', 'Rechargeable Flashlight (USB)', '', 'LED flashlight with 3 modes. USB rechargeable (Type-C).', '', 'A strong handheld light helps you see further, check routes and signal for help.', '["Charge it fully by USB before packing.","Use the lower mode for everyday tasks and the strongest mode only when needed.","Recharge it from a power bank when it runs low."]', 'LED, 3 modes, USB Type-C rechargeable', 'Test it every month and top up the charge.', NULL, NULL, 'rechargeable flashlight usb', '', NULL, 1, 0, 1, 110);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-LGT-003', 'item', 'LGT', 'glow', 'Glow Stick', '', '6-inch glow stick.', '', 'It is a safe light for inside tents and shelters, and a marker so others can see you or find your bag.', '["Bend the stick until you hear it snap inside.","Shake it to start the glow.","Hang it where you need light or use it to mark a spot."]', '6-inch, single-use, no batteries', 'Single use only. Replace it after use or when it passes the date on the pack.', NULL, NULL, '', '', NULL, 1, 0, 1, 120);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-PWR-001', 'item', 'PWR', 'battery', 'Rechargeable Power Bank (10,000 mAh)', '', 'A high-capacity battery pack to recharge phone and USB devices.', '', 'Your phone is your lifeline for warnings, maps and contacting family. A charged power bank keeps it working through an outage.', '["Charge it fully before packing it.","Use it to top up your phone when the battery gets low, not only when it is empty.","Recharge the power bank whenever you have electricity."]', '10,000 mAh, rechargeable, fast charge', 'Recharge it every month, even if unused. Keep it dry.', NULL, NULL, 'how to use power bank emergency', '', NULL, 1, 0, 1, 130);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-PWR-002', 'item', 'PWR', 'plug', 'Multi-Port Charging Cable', '', 'One cable with several heads, to charge different phones and devices.', '', 'Family members often use different phones. One cable that fits several types means nobody is left without power.', '["Plug the cable into your power bank.","Use the tip that fits your phone or device.","Unplug and coil it neatly when you''re done."]', 'Several connector types in one cable', 'Check the cable and heads for damage. Keep it dry.', NULL, NULL, '', '', NULL, 1, 0, 1, 140);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-PWR-003', 'item', 'PWR', 'solar', 'Solar / USB Power Bank', '', 'A power bank you can charge from sunlight or by USB.', '', 'If the power stays out for days, sunlight lets you keep recharging your phone and lights.', '["Charge it fully by USB before packing.","In an outage, place the solar panel facing direct sunlight to recharge it.","Use it to charge your phone, flashlight or headlamp."]', 'Solar panel and USB charging', 'Recharge it every month and keep the panel clean.', NULL, NULL, 'solar power bank how to use', '', NULL, 1, 0, 1, 150);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-COM-001', 'item', 'COM', 'whistle', 'Whistle with Compass', '', 'Whistle with built-in compass.', '', 'A whistle carries further than your voice and uses less energy. The compass helps you keep a direction when landmarks are gone.', '["Blow three short blasts to signal for help, then pause and repeat.","Keep it on a cord where you can reach it quickly.","Hold the compass flat to read the direction."]', 'Signal whistle with built-in compass', 'Test it every month. Keep it clean and dry.', NULL, NULL, 'emergency whistle signal three blasts', '', NULL, 1, 0, 1, 160);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-COM-002', 'item', 'COM', 'phone', 'Waterproof Phone Pouch', '', 'A sealed pouch that keeps your phone dry.', '', 'Rain and floodwater can kill a phone in seconds. A waterproof pouch protects your most important tool.', '["Put your phone inside and close the seal fully.","Test it with no phone inside first to check that it seals.","You can usually use the touchscreen through the pouch."]', 'Waterproof, sealable', 'Check the seal for cracks or tears before each season.', NULL, NULL, '', '', NULL, 1, 0, 1, 170);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-DOC-001', 'item', 'DOC', 'notebook', 'Notebook (A7)', '', 'A small notebook for contact numbers, notes and messages.', '', 'Phones die and networks go down. Writing down key numbers, plans and notes keeps them available.', '["Write important contact numbers on the first page.","Note your family meeting place and evacuation route.","Use it to record what happened and what you still need."]', 'A7 pocket size', 'Keep it in a zip bag so it stays dry. Update the numbers regularly.', NULL, NULL, '', '', NULL, 1, 0, 1, 180);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-DOC-002', 'item', 'DOC', 'pencil', 'Pencil', '', 'Sturdy and durable, no sharpening needed.', '', 'Pens can leak, dry out or fail on wet paper. A pencil keeps working.', '["Keep it with the notebook.","Use it to write notes, messages or directions.","Sharpen it with your multi-tool if needed."]', 'Durable, no sharpening needed', 'Keep it stored with the notebook.', NULL, NULL, '', '', NULL, 1, 0, 1, 190);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-DOC-003', 'item', 'DOC', 'doc', 'Waterproof Zip Bags (L)', '', 'Large waterproof zip bags for documents, clothes and electronics.', '', 'IDs, papers and spare clothes are useless once soaked. Zip bags keep them dry through rain and flooding.', '["Put your documents, cash and spare clothes in separate bags.","Press out the air and close the zip fully.","Keep the most important documents in the bag on top."]', 'Large, 28 × 38, zip seal', 'Check them for holes and replace any that don''t seal.', NULL, NULL, '', '', NULL, 1, 0, 1, 200);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTH-001', 'item', 'WTH', 'blanket', 'Emergency Thermal Blanket', '', 'A light foil blanket that keeps in body heat. 2 included in the KIDAN Black.', '', 'After getting wet in rain or floodwater, your body loses heat fast, even in warm weather. A thermal blanket helps keep you warm.', '["Unfold it fully.","Wrap it around your body, shiny side in, covering your head if possible.","Use it under a tarp or tent for extra warmth."]', 'Foil emergency blanket, folds small', 'Keep it sealed until needed. Replace it once it has been used.', NULL, NULL, 'how to use emergency thermal blanket', '', NULL, 1, 0, 1, 210);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTH-002', 'item', 'WTH', 'rain', 'Lightweight Rain Poncho', '', 'Compact and durable.', '', 'Staying dry helps you stay warm and healthy during typhoon rains.', '["Unfold it and put it on over your clothes.","Wear it over your bag to keep the bag dry too.","Shake it dry and fold it after use."]', 'Lightweight, packable', 'Check it for tears. Dry it fully before packing it again.', NULL, NULL, '', '', NULL, 1, 0, 1, 220);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTH-003', 'item', 'WTH', 'trash', 'Heavy-Duty Garbage Bags (3XL)', '', '', '', 'Extra-large bags have many uses: a rain cover, a ground sheet, a bag liner, or sealing away rubbish and waste.', '["Line your pouch or bag with one to keep the contents dry.","Cut a head hole to make an emergency rain cover.","Use one to collect and seal away rubbish."]', 'Heavy-duty, 3XL', 'Keep them folded flat. Replace any that are used or torn.', NULL, NULL, '', '', NULL, 1, 0, 1, 230);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTH-004', 'item', 'WTH', 'tent', '2-Person Tent', '', '2-person outdoor, waterproof emergency camping tent.', '', 'Evacuation centres can be crowded. A tent gives your family dry, private space to rest.', '["Choose high, flat ground away from rivers and slopes.","Lay out the tent, then put in the poles and raise it.","Stake down all corners and tie the guy lines firmly in wind."]', '2-person, waterproof', 'Practise setting it up at home. Dry it fully before packing it away.', NULL, NULL, 'how to set up 2 person tent', '', NULL, 1, 0, 1, 240);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-WTH-005', 'item', 'WTH', 'sleep', 'Sleeping Bag', '', 'Compact and waterproof.', '', 'Rest keeps you able to make good decisions. A sleeping bag keeps you warm and off the cold floor.', '["Unpack it and let it fluff up before use.","Lay it on a dry surface, or on a garbage bag as a ground sheet.","Roll it tightly and pack it in its sack after use."]', 'Compact, waterproof', 'Air it out and keep it dry. Store it loosely when not in the bag for long periods.', NULL, NULL, '', '', NULL, 1, 0, 1, 250);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-HYG-001', 'item', 'HYG', 'towel', 'Compressed Towel (70 × 140 cm)', '', '', '', 'Drying off after rain or a wash helps prevent chills and skin problems.', '["Add a little water to the compressed tablet.","Unroll it to its full size.","Use it to dry off or clean up, then dispose of it."]', 'Disposable, 70 × 140 cm when open', 'Keep it sealed and dry until needed.', NULL, NULL, '', '', NULL, 1, 0, 1, 260);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-HYG-002', 'item', 'HYG', 'hygiene', 'Portable Car Urine Bags', '', 'Disposable pee and vomit bags.', '', 'Toilets may be flooded, broken or unavailable during evacuation. These bags keep things clean and private, and also help with motion sickness while travelling.', '["Open the bag and use it following the instructions on the pack.","Seal it tightly after use.","Dispose of it properly in a rubbish bag."]', 'Single-use, sealable', 'Keep enough for 72 hours. Replace any you use.', NULL, NULL, '', '', NULL, 1, 0, 1, 270);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-HYG-003', 'item', 'HYG', 'hygiene', 'Floss', '', 'Dental floss.', '', 'Keeping your mouth clean helps you stay healthy. Floss can also be used to tie or mend things.', '["Use it after eating to clean between your teeth.","Use a length as strong thread for small repairs if needed."]', 'Dental floss', 'Replace it when it runs low.', NULL, NULL, '', '', NULL, 1, 0, 1, 280);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-HYG-004', 'item', 'HYG', 'hygiene', 'Wipes', '', '', '', 'Clean hands prevent illness, especially when water is limited.', '["Wipe your hands before eating and after using the toilet.","Use them to freshen up when you can''t bathe.","Seal the pack after each use so they don''t dry out."]', 'Wet wipes', 'Check the pack is still sealed and moist. Replace it when opened for long.', NULL, NULL, '', '', NULL, 1, 0, 1, 290);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-TLS-002', 'item', 'TLS', 'scissors', 'Folding Scissors (Stainless)', '', 'Stainless steel scissors that fold for safe packing.', '', 'Useful for cutting bandages, tape, cord, plastic and fabric.', '["Unfold them fully before cutting.","Cut away from your body and other people.","Fold them closed before packing."]', 'Stainless steel, folding', 'Wipe them dry to keep them sharp and rust-free.', NULL, NULL, '', '', NULL, 1, 0, 1, 300);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-TLS-003', 'item', 'TLS', 'rope', 'Paracord', '', '31 meters, 7-core, 4 mm diameter rope.', '', 'Cord lets you put up a shelter, hang a tarp, secure gear or make a clothesline.', '["Measure the length you need before cutting.","Tie it off with a secure knot.","If you know how, seal cut ends with a little heat so they don''t fray."]', '31 m, 7-core, 4 mm diameter', 'Coil it neatly so it doesn''t tangle. Replace damaged lengths.', NULL, NULL, 'paracord knots basics', '', NULL, 1, 0, 1, 310);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-TLS-004', 'item', 'TLS', 'ziptie', 'Zip Ties', '', '', '', 'Zip ties fix, bundle and secure things in seconds, from tent poles to broken straps.', '["Choose the short or long tie for the job.","Loop it around and pull it tight through the lock.","Trim the extra tail with scissors."]', '100 mm and 200 mm', 'Replace any you use.', '["100 mm","200 mm"]', NULL, '', '', NULL, 1, 0, 1, 320);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-SRV-001', 'item', 'SRV', 'fish', 'Fishing Kit', '', 'For fresh and salt water fishing.', '', 'If food runs short over several days, fishing gives you another source of food. Only fish in safe, clean water, never in floodwater.', '["Wind the nylon thread around the wood dowel or tin can as your line.","Tie on a swivel, then a hook. Use the deep or shallow hook to match the water.","Add a sinker above the hook so it sinks.","Follow the instruction sticker in the kit."]', 'Hooks, sinkers, swivel, nylon thread, tin can, wood dowel, instruction sticker', 'Check the hooks for rust and keep the kit dry.', '["Hook (deep water)","Hook (shallow water)","Sinker (10 g)","Sinker (5 g)","Swivel","Nylon thread","Tin can (silver)","Wood dowel","Sticker for instructions (8 × 5 cm)"]', NULL, 'survival fishing kit how to use', '', NULL, 1, 0, 1, 330);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-SRV-002', 'item', 'SRV', 'trap', 'Trap Kit', '', 'Dowels, thread and instructions for setting a simple snare.', '', 'If you are stranded for several days, a simple trap can help you catch small game for food.', '["Read the instruction stickers in the kit first.","Set the trap using the dowels and thread as shown.","Check it regularly and handle any catch safely."]', 'Dowels, brown and black thread, instruction stickers', 'Keep the thread dry and untangled.', '["Dowels","Thread (brown)","Thread (black)","Sticker (30 × 15)","Sticker (50 × 30)"]', NULL, '', '', NULL, 2, 0, 1, 340);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-SRV-003', 'item', 'SRV', 'fire', 'Fire Starter Kit', '', 'A ferro rod and cotton balls.', '', 'Fire gives warmth, boils water and helps you signal. Cotton balls catch a spark and burn long enough to light kindling.', '["Prepare dry kindling and small sticks in a safe, open spot.","Pull a cotton ball apart and fluff it out.","Scrape the ferro rod firmly to throw sparks onto the cotton ball.","Feed the flame slowly with small sticks. Never leave a fire unattended."]', 'Ferro rod, cotton balls, tin can, instruction sticker', 'Keep the cotton balls dry in the sealed tin. Practise using it at home.', '["Ferro rod","Cotton balls","Tin can (black)","Sticker (50 × 30)"]', NULL, 'how to use ferro rod cotton ball', '', NULL, 1, 0, 1, 350);
INSERT INTO products (serial, kind, cat, icon, name, label, short_text, summary, why, steps, spec, maintain, parts, specs, search_q, video, price, photos, photo_hidden, sold_separately, sort) VALUES ('K72-SRV-004', 'item', 'SRV', 'slingshot', 'Slingshot', '', '"Tirador"', '', 'It can be used to signal by launching small objects, to scare off animals, or to hunt small game when stranded for several days.', '["Hold the handle firmly with your arm straight.","Place a small stone in the pouch and pull back to your cheek.","Aim away from people, windows and animals you don''t intend to hit, then release."]', 'Wooden frame, rubber band', 'Keep the band out of the sun and replace it if it cracks.', NULL, NULL, '', '', NULL, 1, 0, 1, 360);
