INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('A', 'bag', 'Bag Preparation', 'Why 72 hours, local hazards, packing and carrying.', '["Why 72 hours?","Knowing local hazards","Selecting the right bag","Packing and compartment organisation","Weight distribution and ergonomics","Inspection routines and carrying technique"]', 'how to pack a 72 hour go bag', 'https://youtu.be/6_uHsU6K71Y', 10);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('B', 'water', 'Water', 'Preparation, storage, carrying, safety and purification.', '["Daily water needs per person","Safe storage and rotation","Carrying water efficiently","Purification and filtration","Floodwater dangers"]', 'emergency water purification methods', '', 20);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('C', 'food', 'Food', 'Emergency selection, safe storage and non-gas preparation.', '["Choosing ready-to-eat food","Safe storage and expiry tracking","Non-gas preparation methods","Rationing across 72 hours"]', 'no cook emergency food', '', 30);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('D', 'aid', 'First Aid', 'Kit contents, basic demonstrations, critical medication.', '["Kit contents and layout","Wound cleaning and dressing","Bleeding control","Sprains and immobilisation","Critical medication management"]', 'basic first aid training bleeding control', '', 40);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('E', 'battery', 'Power & Light', 'Lights, battery care, power bank and phone power.', '["Flashlight and headlamp use","Battery care and storage","Power bank optimisation","Phone power management"]', 'save phone battery power outage', '', 50);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('F', 'radio', 'Communication', 'Emergency channels, phone prep, radio and family protocol.', '["Official emergency channels","Phone preparation","Radio operation","Family communication during outages"]', 'family emergency communication plan', '', 60);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('G', 'fire', 'Fire & Light', 'Safe use of fire-starting equipment and light tools.', '["Lighters, matches and ferro rods","Fire safety and ventilation","Flame safety indoors","Light discipline in shelters"]', 'fire starting safety ferro rod', '', 70);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('H', 'tent', 'Shelter & Weather', 'Rain protection, temporary shelter, keeping gear dry.', '["Rain protection layers","Setting up a tarp shelter","Choosing a safe spot","Keeping gear dry"]', 'emergency tarp shelter rain', '', 80);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('I', 'route', 'Navigation & Movement', 'Offline navigation, safe routes, moving with gear.', '["Paper map and compass navigation","Safe route selection in floods","Moving with a loaded bag","Group movement and headcounts"]', 'map and compass navigation basics', '', 90);
INSERT INTO modules (code, icon, name, short_text, lessons, search_q, video, sort) VALUES ('J', 'rope', 'Cordage & Basic Tools', 'Essential knots, cordage uses and emergency tools.', '["Bowline, clove hitch, taut-line hitch","Lashing and securing gear","Multi-tool use and safety","Improvised repairs"]', 'essential knots survival', '', 100);
